// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address actor, uint8 roleSel) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        bytes32[3] memory roles = [
            c.PROPOSER_ROLE(),
            c.EXECUTOR_ROLE(),
            c.TIMELOCK_ADMIN_ROLE()
        ];
        bytes32 role = roles[bound(roleSel, 0, 2)];

        // grant the role to the fuzzed actor; the contract itself holds TIMELOCK_ADMIN_ROLE
        vm.prank(address(c));
        c.grantRole(role, actor);
        assertTrue(c.hasRole(role, actor));

        // the actor renounces their own role
        vm.prank(actor);
        bool ok;
        try c.renounceRole(role, actor) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: self-renunciation always succeeds and removes the held role.
        assertTrue(ok && !c.hasRole(role, actor));
    }
}
